var a=`1432-taro-with-coconut-cream`;var i=`world-1432`;var o=`FM`;var n=`oceania`;var r=4;var s=58;var c={en:`Taro with Coconut Cream`,ua:`Таро з кокосовими вершками`};var l={en:`Federated States of Micronesia-style cooked taro served in coconut cream: a simple Pacific island staple.`,ua:`Варене таро з кокосовими вершками у стилі Федеративних Штатів Мікронезії, проста острівна основна страва.`};var u=[{en:`Peel purchased edible taro and cut it into equal-sized chunks; rinse away surface starch.`,ua:`Очистіть придбане харчове таро й наріжте однаковими шматками; промийте від поверхневого крохмалю.`,t:[`peeling`],m:10,i:[[`taro-root`,900,`g`]]},{en:`Boil taro in fresh water for 30–40 minutes until soft throughout; discard the cooking water.`,ua:`Варіть таро у чистій воді 30–40 хвилин до повної м’якості; злийте воду.`,t:[`boiling`,`draining`],m:40,i:[[`water`,1800,`ml`]]},{en:`Heat coconut cream gently with a small pinch of salt, stirring so it does not split.`,ua:`Обережно нагрійте кокосові вершки з невеликою дрібкою солі, помішуючи, щоб не розшарувалися.`,t:[`gentle-simmering`],m:6,i:[[`coconut-cream`,370,`ml`],[`sea-salt`,3,`g`]]},{en:`Spoon the warm cream over cooked taro and serve immediately.`,ua:`Полийте готове таро теплими кокосовими вершками й одразу подавайте.`,t:[`garnishing`],m:2,i:[]}];var m={slug:a,id:i,country:`FM`,region:n,servings:4,minutes:58,title:c,text:l,steps:u};export{o as country,m as default,i as id,s as minutes,n as region,r as servings,a as slug,u as steps,l as text,c as title};